layer.css:
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid rgba(0, 0, 0, 0.125); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-bg); border-radius: 0px; font-family: "source sans pro", -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol"; font-size: 22.5px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: "source sans pro", -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol"; font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 16px; padding-bottom: 16px; padding-left: 16px; transition: all }
[data-ryt="button"] { color: rgb(33, 37, 41); background-color: rgb(240, 240, 240); border-top: 1px solid rgb(240, 240, 240); border-right: 1px solid rgb(240, 240, 240); border-bottom: 1px solid rgb(240, 240, 240); border-left: 1px solid rgb(240, 240, 240); border-radius: 3.2px; font-family: "source sans pro", -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol"; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(33, 37, 41); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 8px; padding-bottom: 4px; padding-left: 8px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #8d8d8d; background-color: rgb(246, 246, 246); border-radius: 4px; font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(153, 153, 153); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out }
[data-ryt="category"], [data-ryt="tags"] li { color: #8d8d8d; border-radius: 0px; font-family: FontAwesome; font-weight: 400; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(153, 153, 153); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: "source sans pro", -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol"; font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #8d8d8d; font-family: "source sans pro", -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol"; font-size: 14.4px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(153, 153, 153); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 4px }
[data-ryt="rec-card"] [data-ryt="title"] { color: #5b90bc; border-radius: 0px; font-family: "source sans pro", -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol"; font-size: 23.625px; font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(97, 156, 205); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(33, 37, 41); background-color: rgb(218, 224, 229); color: rgb(54, 118, 171); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(33, 37, 41); background-color: rgb(221, 221, 221) }
[data-ryt="button"]:hover { color: rgb(0, 86, 179); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(33, 37, 41); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: var(--ryt-bg); background-color: rgb(90, 98, 104); border-top-color: rgb(84, 91, 98); border-right-color: rgb(84, 91, 98); border-bottom-color: rgb(84, 91, 98); border-left-color: rgb(84, 91, 98); color: rgb(54, 118, 171); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: var(--ryt-text); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(33, 37, 41); background-color: rgb(221, 221, 221); border-top-color: rgb(215, 215, 215); border-right-color: rgb(215, 215, 215); border-bottom-color: rgb(215, 215, 215); border-left-color: rgb(215, 215, 215) }
[data-ryt="nav"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: color-mix(in srgb, var(--ryt-bg) 75%, transparent); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(36, 80, 115); color: var(--ryt-header-text) }
[data-ryt="brand"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: var(--ryt-bg); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
